   else el.addEventListener('click',e=>{if(!confirm(el.dataset.confirm||'Lanjutkan tindakan ini?'))e.preventDefault()});
 });
 $$('form').forEach(form=>form.addEventListener('submit',(event)=>{if(event.defaultPrevented||form.matches('[data-quick-add]'))return;const button=form.querySelector('button[type=submit],button:not([type])');if(button&&!button.disabled){button.dataset.originalLabel=button.innerHTML;button.innerHTML='<i class="fa-solid fa-circle-notch fa-spin"></i> Memproses...';button.disabled=true}}));
 $$('form[data-unsaved-form]').forEach(form=>{let dirty=false;form.addEventListener('input',()=>dirty=true);form.addEventListener('change',()=>dirty=true);form.addEventListener('submit',()=>dirty=false);window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}})});
 // Live server-side filters: text search is debounced; select/date filters apply immediately.
 $$('form[data-live-filter]').forEach(form=>{
   let timer=null;
   const apply=()=>{
     clearTimeout(timer);
     const url=new URL(form.action||location.href,location.origin);
     const params=new URLSearchParams(new FormData(form));
     // A new filter starts from the first page; unrelated query parameters are not retained.
     url.search=params.toString();
     location.assign(url.toString());
   };
   form.querySelectorAll('input:not([type=hidden]):not([type=submit]):not([type=date])').forEach(input=>{
