   form.addEventListener('reset',()=>setTimeout(apply,0));
 });
 $$('[data-filter-table]').forEach(input=>{const table=$(input.dataset.filterTable);input.addEventListener('input',()=>{$$('tbody tr',table).forEach(row=>row.hidden=!row.innerText.toLowerCase().includes(input.value.toLowerCase()))})});
 $$('table:not([data-no-sort])').forEach(table=>{const body=$('tbody',table);if(!body)return;$$('thead th',table).forEach((th,index)=>{th.title=(th.title?th.title+' · ':'')+'Urutkan kolom ini';th.addEventListener('click',()=>{const rows=$$('tr',body);const ascending=th.dataset.sortDirection!=='asc';$$('thead th',table).forEach(h=>{h.dataset.sortDirection='';h.removeAttribute('aria-sort')});th.dataset.sortDirection=ascending?'asc':'desc';th.setAttribute('aria-sort',ascending?'ascending':'descending');rows.sort((a,b)=>{const av=a.children[index]?.innerText.trim()||'',bv=b.children[index]?.innerText.trim()||'';return av.localeCompare(bv,'id',{numeric:true,sensitivity:'base'})*(ascending?1:-1)}).forEach(row=>body.appendChild(row))})})});
 // Searchable select: input suggestions map back to the original select value.
 $$('select[data-searchable-select]').forEach((select,index)=>{
   const wrapper=document.createElement('div');wrapper.className='searchable-select-wrap';
   const input=document.createElement('input');input.type='text';input.className='searchable-select-input';input.setAttribute('list','searchable-options-'+index);input.placeholder=select.dataset.searchPlaceholder||'Ketik untuk mencari...';input.setAttribute('aria-label',select.getAttribute('aria-label')||'Cari pilihan dropdown');input.autocomplete='off';
